import React, { useEffect, useState } from 'react';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import { Card, Button, Typography, Grid, Alert } from '@mui/material';

const ManagerDashboard = () => {
  const { user } = useAuth();
  const [pending, setPending] = useState([]);
  const [success, setSuccess] = useState('');
  const [error, setError] = useState('');

  const fetchRequests = () => {
    api.pendingRequests(user.token).then(setPending).catch(() => setPending([]));
  };
  useEffect(() => { fetchRequests(); }, [user]);

  const handleDecision = (id, status) => {
    setError(''); setSuccess('');
    api.decideLeave(id, status, user.token)
      .then(() => {
        setSuccess(`Leave ${status.toLowerCase()}ed.`);
        fetchRequests();
      })
      .catch(e => setError(e.message));
  };

  return (
    <div>
      <Typography variant="h5" sx={{ mb: 2 }}>Pending Leave Requests</Typography>
      {success && <Alert severity="success">{success}</Alert>}
      {error && <Alert severity="error">{error}</Alert>}
      <Grid container spacing={2}>
        {pending.map(req => (
          <Grid item xs={12} md={6} key={req.id}>
            <Card sx={{ p: 2, mb: 1 }}>
              <Typography><b>{req.employeeName || req.username}:</b> {req.leaveType} ({req.fromDate} → {req.toDate})</Typography>
              <Typography variant="body2">Reason: {req.reason}</Typography>
              <Button
                sx={{ mt: 1, mr: 1 }}
                variant="contained"
                color="success"
                onClick={() => handleDecision(req.id, 'APPROVED')}
              >Approve</Button>
              <Button
                sx={{ mt: 1 }}
                variant="contained"
                color="error"
                onClick={() => handleDecision(req.id, 'REJECTED')}
              >Reject</Button>
            </Card>
          </Grid>
        ))}
        {!pending.length && <Typography sx={{ px: 2 }}>No pending requests.</Typography>}
      </Grid>
    </div>
  );
};

export default ManagerDashboard;
